
.world-section {
  padding: 14px 16px;
  background: linear-gradient(135deg, var(--c-bg-deep) 0%, var(--c-bg-panel) 100%);
  border-bottom: 1px solid var(--c-border);
}

.header-row {
  display: flex;
  align-items: center;
  gap: 8px;
  margin-bottom: 6px;

  &:last-child {
    margin-bottom: 0;
  }
}

.label {
  font-size: 14px;
  flex-shrink: 0;
}

.value {
  font-size: 12px;
  color: var(--c-text-dim);
}

.location {
  color: var(--c-accent);
  font-weight: 600;
}
