
.character-panel {
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.char-section {
  border: 1px solid var(--c-border);
  border-radius: 8px;
  overflow: hidden;
  background: var(--c-bg-deep);
}

.char-header {
  display: flex;
  align-items: center;
  padding: 10px 12px;
  cursor: pointer;
  background: var(--c-bg-panel);
  transition: background 0.2s ease;
  gap: 8px;

  &:hover {
    background: rgba(180, 140, 255, 0.1);
  }
}

.char-name {
  font-weight: 700;
  color: var(--c-primary);
  font-size: 14px;
  flex: 1;
}

.char-realm {
  font-size: 11px;
  color: var(--c-accent);
  background: rgba(255, 216, 102, 0.1);
  padding: 2px 8px;
  border-radius: 4px;
  border: 1px solid rgba(255, 216, 102, 0.2);
}

.toggle-icon {
  font-size: 10px;
  color: var(--c-text-muted);
}

.char-body {
  padding: 10px 12px;
}

.stat-row {
  display: flex;
  flex-direction: column;
  gap: 8px;
  margin-bottom: 10px;
  padding-bottom: 10px;
  border-bottom: 1px solid var(--c-border);
}

.stat-bar-group {
  display: flex;
  align-items: center;
  gap: 8px;
}

.stat-label {
  font-size: 11px;
  color: var(--c-text-dim);
  width: 60px;
  flex-shrink: 0;
}

.bar-track {
  flex: 1;
  height: 6px;
  background: rgba(255, 255, 255, 0.06);
  border-radius: 3px;
  overflow: hidden;
}

.bar-fill {
  height: 100%;
  border-radius: 3px;
  transition: width 0.5s ease;

  &.favor {
    background: linear-gradient(90deg, #ff6b8a, #ff4d6d);
  }

  &.trust {
    background: linear-gradient(90deg, #66ccff, #3399ff);
  }
}

.stat-num {
  font-size: 11px;
  color: var(--c-text);
  width: 28px;
  text-align: right;
  font-family: var(--font-mono);
}

.info-item {
  display: flex;
  gap: 6px;
  margin-bottom: 6px;
  font-size: 12px;
  line-height: 1.5;

  &:last-child {
    margin-bottom: 0;
  }
}

.info-label {
  color: var(--c-text-muted);
  flex-shrink: 0;
  width: 56px;
}

.info-value {
  color: var(--c-text-dim);
  word-break: break-all;

  &.inner {
    color: var(--c-primary-dim);
    font-style: italic;
  }
}

.delete-btn {
  margin-top: 10px;
  width: 100%;
  padding: 6px 0;
  background: rgba(255, 102, 136, 0.08);
  border: 1px solid rgba(255, 102, 136, 0.2);
  border-radius: 6px;
  color: var(--c-danger);
  font-size: 11px;
  font-family: var(--font-main);
  cursor: pointer;
  transition: all 0.2s ease;

  &:hover {
    background: rgba(255, 102, 136, 0.15);
    border-color: rgba(255, 102, 136, 0.4);
  }
}

.empty-hint {
  text-align: center;
  color: var(--c-text-muted);
  font-size: 12px;
  padding: 16px 0;
}
