
.inventory-panel {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.player-info {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.info-row {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 12px;
}

.label {
  color: var(--c-text-muted);
  width: 56px;
  flex-shrink: 0;
}

.value {
  color: var(--c-text);

  &.realm {
    color: var(--c-primary);
    font-weight: 600;
  }

  &.gold {
    color: var(--c-accent);
    font-weight: 600;
    font-family: var(--font-mono);
  }
}

.divider {
  height: 1px;
  background: var(--c-border);
  margin: 4px 0;
}

.section-title {
  font-size: 12px;
  font-weight: 600;
  color: var(--c-primary);
  margin-bottom: 4px;
}

.item-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.item-card {
  background: var(--c-bg-panel);
  border: 1px solid var(--c-border);
  border-radius: 6px;
  padding: 8px 10px;
}

.item-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 4px;
}

.item-name {
  font-size: 12px;
  font-weight: 600;
  color: var(--c-text);
}

.item-count {
  font-size: 11px;
  color: var(--c-accent);
  font-family: var(--font-mono);
  background: rgba(255, 216, 102, 0.1);
  padding: 1px 6px;
  border-radius: 3px;
}

.item-desc {
  font-size: 11px;
  color: var(--c-text-muted);
  line-height: 1.4;
}

.empty-hint {
  text-align: center;
  color: var(--c-text-muted);
  font-size: 12px;
  padding: 16px 0;
}
