
.map-panel {
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.continent-tabs {
  display: flex;
  gap: 4px;
  flex-wrap: wrap;
}

.continent-btn {
  flex: 1;
  min-width: 0;
  padding: 6px 4px;
  background: var(--c-bg-panel);
  border: 1px solid var(--c-border);
  border-radius: 6px;
  color: var(--c-text-muted);
  font-size: 11px;
  font-family: var(--font-main);
  cursor: pointer;
  transition: all 0.2s ease;
  white-space: nowrap;

  &:hover {
    background: rgba(180, 140, 255, 0.08);
    color: var(--c-text);
  }

  &.active {
    background: rgba(180, 140, 255, 0.15);
    border-color: var(--c-primary);
    color: var(--c-primary);
    font-weight: 600;
  }
}

.map-container {
  border: 1px solid var(--c-border);
  border-radius: 8px;
  overflow: hidden;
  background: var(--c-bg-deep);
}

.map-svg {
  width: 100%;
  display: block;
}

.continent-shape {
  cursor: pointer;
  transition:
    fill 0.3s ease,
    stroke 0.3s ease;
}

.continent-label {
  pointer-events: none;
  font-family: var(--font-main);
  letter-spacing: 2px;
}

.city-dot {
  cursor: pointer;
  transition:
    r 0.2s ease,
    fill 0.2s ease;

  &:hover {
    filter: brightness(1.3);
  }
}

.city-label {
  pointer-events: none;
  font-family: var(--font-main);
}

.pulse-ring {
  animation: pulse 2s infinite ease-out;
}

@keyframes pulse {
  0% {
    r: 6;
    opacity: 0.8;
  }
  100% {
    r: 16;
    opacity: 0;
  }
}

.move-panel {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 12px;
  background: var(--c-bg-panel);
  border: 1px solid var(--c-border);
  border-radius: 8px;
}

.move-info {
  flex: 1;
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.move-target {
  font-size: 12px;
  font-weight: 600;
  color: var(--c-primary);
}

.move-desc {
  font-size: 11px;
  color: var(--c-text-muted);
}

.move-btn {
  flex-shrink: 0;
  padding: 8px 16px;
  background: linear-gradient(135deg, var(--c-primary), #9060e8);
  border: none;
  border-radius: 6px;
  color: white;
  font-size: 12px;
  font-weight: 600;
  font-family: var(--font-main);
  cursor: pointer;
  transition: all 0.2s ease;
  box-shadow: 0 2px 8px rgba(180, 140, 255, 0.3);

  &:hover:not(:disabled) {
    transform: translateY(-1px);
    box-shadow: 0 4px 12px rgba(180, 140, 255, 0.4);
  }

  &:active:not(:disabled) {
    transform: translateY(0);
  }

  &:disabled {
    opacity: 0.6;
    cursor: not-allowed;
  }
}

.current-hint {
  text-align: center;
  font-size: 12px;
  color: var(--c-success);
  padding: 8px;
  background: rgba(102, 255, 178, 0.06);
  border: 1px solid rgba(102, 255, 178, 0.15);
  border-radius: 6px;
}
